178	diff --git a/cms/src/middlewares/form-field-integrity.test.ts b/cms/src/middlewares/form-field-integrity.test.ts
179	new file mode 100644
180	index 0000000..bd4b3a3
181	--- /dev/null
182	+++ b/cms/src/middlewares/form-field-integrity.test.ts
183	@@ -0,0 +1,42 @@
184	+import { describe, expect, it } from 'vitest';
185	+import { checkFormFieldIntegrity, readCountryPayload } from './form-field-integrity';
186	+
187	+describe('US-01 · Edge Cases form field integrity', () => {
188	+  const existing = [
189	+    { documentId: 'a1', key: 'plate' },
190	+    { documentId: 'a2', key: 'email' },
191	+  ];
192	+
193	+  it('rejects a field without country', () => {
194	+    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: null }, [])).toBe('El campo debe tener un país.');
195	+  });
196	+
197	+  it('rejects a duplicate key in the same country', () => {
198	+    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'co', selfDocumentId: 'new' }, existing)).toBe(
199	+      'Ya existe un campo con la clave «plate» para este país.',
200	+    );
201	+  });
202	+
203	+  it('allows the same key in another country', () => {
204	+    expect(checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'cl' }, [])).toBeNull();
205	+  });
206	+
207	+  it('allows an update that keeps its own key', () => {
208	+    expect(
209	+      checkFormFieldIntegrity({ key: 'plate', countryDocumentId: 'co', selfDocumentId: 'a1' }, existing),
210	+    ).toBeNull();
211	+  });
212	+
213	+  it('allows a valid new field', () => {
214	+    expect(checkFormFieldIntegrity({ key: 'city', countryDocumentId: 'co' }, existing)).toBeNull();
215	+  });
216	+
217	+  it('reads the relation payload shapes', () => {
218	+    expect(readCountryPayload(undefined)).toEqual({ present: false, ref: null });
219	+    expect(readCountryPayload('abc')).toEqual({ present: true, ref: 'abc' });
220	+    expect(readCountryPayload({ connect: [{ documentId: 'abc' }] })).toEqual({ present: true, ref: 'abc' });
221	+    expect(readCountryPayload({ set: ['abc'] })).toEqual({ present: true, ref: 'abc' });
222	+    expect(readCountryPayload({ connect: [] })).toEqual({ present: true, ref: null });
223	+    expect(readCountryPayload(3)).toEqual({ present: true, ref: 3 });
224	+  });
225	+});
226	diff --git a/cms/src/middlewares/form-field-integrity.ts b/cms/src/middlewares/form-field-integrity.ts
227	new file mode 100644
228	index 0000000..0129145
229	--- /dev/null
230	+++ b/cms/src/middlewares/form-field-integrity.ts
231	@@ -0,0 +1,106 @@
232	+import type { Core } from '@strapi/strapi';
233	+import { errors } from '@strapi/utils';
234	+
235	+const UID = 'api::form-field.form-field';
236	+const ACTIONS = ['create', 'update', 'publish'];
237	+
238	+export interface FormFieldIntegrityInput {
239	+  key?: string | null;
240	+  countryDocumentId?: string | null;
241	+  selfDocumentId?: string | null;
242	+}
243	+
244	+export interface ExistingKey {
245	+  documentId: string;
246	+  key: string;
247	+}
248	+
249	+/** Pure rule: a field needs a country, and its key is unique within that country. */
250	+export function checkFormFieldIntegrity(
251	+  input: FormFieldIntegrityInput,
252	+  existingSameCountryKeys: ExistingKey[],
253	+): string | null {
254	+  if (!input.countryDocumentId) return 'El campo debe tener un país.';
255	+  const duplicate = existingSameCountryKeys.some(
256	+    (f) => f.key === input.key && f.documentId !== input.selfDocumentId,
257	+  );
258	+  if (duplicate) return `Ya existe un campo con la clave «${input.key}» para este país.`;
259	+  return null;
260	+}
261	+
262	+type Ref = string | number;
263	+
264	+function refOf(item: unknown): Ref | null {
265	+  if (typeof item === 'string' || typeof item === 'number') return item;
266	+  if (item && typeof item === 'object') {
267	+    const o = item as Record<string, unknown>;
268	+    return (o.documentId ?? o.id ?? null) as Ref | null;
269	+  }
270	+  return null;
271	+}
272	+
273	+/** Reads the country from the relation payload shapes Strapi accepts. `present=false` means untouched. */
274	+export function readCountryPayload(value: unknown): { present: boolean; ref: Ref | null } {
275	+  if (value === undefined) return { present: false, ref: null };
276	+  if (value === null) return { present: true, ref: null };
277	+  if (typeof value === 'string' || typeof value === 'number') return { present: true, ref: value };
278	+  if (typeof value === 'object') {
279	+    const v = value as Record<string, unknown>;
280	+    const list = v.set ?? v.connect;
281	+    if (Array.isArray(list)) return { present: true, ref: refOf(list[0]) };
282	+    if (Array.isArray(v.disconnect) && v.disconnect.length > 0) return { present: true, ref: null };
283	+    if (v.documentId !== undefined || v.id !== undefined) return { present: true, ref: refOf(v) };
284	+  }
285	+  return { present: false, ref: null };
286	+}
287	+
288	+export function registerFormFieldIntegrity(strapi: Core.Strapi): void {
289	+  strapi.documents.use(async (context, next) => {
290	+    if (context.uid !== UID || !ACTIONS.includes(context.action)) return next();
291	+
292	+    const params = (context.params ?? {}) as { documentId?: string; data?: Record<string, unknown> };
293	+    const data = params.data ?? {};
294	+    const selfDocumentId = params.documentId ?? null;
295	+
296	+    type Existing = { key?: string; country?: { documentId: string } | null } | null;
297	+    let existing = null as Existing;
298	+    if (selfDocumentId) {
299	+      existing = (await strapi.documents(UID).findOne({
300	+        documentId: selfDocumentId,
301	+        populate: { country: { fields: ['documentId'] } },
302	+        status: 'draft',
303	+      })) as Existing;
304	+    }
305	+
306	+    const key = (data.key as string | undefined) ?? existing?.key ?? null;
307	+
308	+    const { present, ref } = readCountryPayload(data.country);
309	+    let countryDocumentId: string | null = null;
310	+    if (present) {
311	+      if (typeof ref === 'number') {
312	+        const found = (await strapi.db.query('api::country.country').findOne({ where: { id: ref } })) as {
313	+          documentId: string;
314	+        } | null;
315	+        countryDocumentId = found?.documentId ?? null;
316	+      } else {
317	+        countryDocumentId = ref;
318	+      }
319	+    } else {
320	+      countryDocumentId = existing?.country?.documentId ?? null;
321	+    }
322	+
323	+    let others: ExistingKey[] = [];
324	+    if (countryDocumentId) {
325	+      // Draft and published versions share a documentId, so excluding it covers both.
326	+      others = (await strapi.documents(UID).findMany({
327	+        filters: { country: { documentId: countryDocumentId } },
328	+        fields: ['key'],
329	+        status: 'draft',
330	+      })) as ExistingKey[];
331	+    }
332	+
333	+    const message = checkFormFieldIntegrity({ key, countryDocumentId, selfDocumentId }, others);
334	+    if (message) throw new errors.ValidationError(message);
335	+    return next();
336	+  });
337	+}
