440	+import type { Core } from '@strapi/strapi';
441	+import {
442	+  CL_MOBILE_PATTERN,
443	+  CL_PLATE_PATTERN,
444	+  CL_RUT_PATTERN,
445	+  CO_DOCUMENT_NUMBER_PATTERN,
446	+  CO_MOBILE_PATTERN,
447	+  CO_PLATE_PATTERN,
448	+  EMAIL_PATTERN,
449	+  FULL_NAME_PATTERN,
450	+} from './form-field-patterns';
451	+
452	+const FIELD_UID = 'api::form-field.form-field';
453	+const COUNTRY_UID = 'api::country.country';
454	+const DEFAULT_LEGAL_AGE = 18;
455	+
456	+interface SeedOption {
457	+  label: string;
458	+  value: string;
459	+}
460	+
461	+interface SeedField {
462	+  key: string;
463	+  label: string;
464	+  type: 'text' | 'number' | 'select' | 'date' | 'checkbox';
465	+  section: 'policyholder' | 'vehicle';
466	+  order: number;
467	+  helpText?: string;
468	+  placeholder?: string;
469	+  errorMessage: string;
470	+  options?: SeedOption[];
471	+  validations?: { pattern?: string; validators?: Array<{ name: string; value?: number }> };
472	+}
473	+
