116	/** Groups CMS fields by section, sorted by `order` (stable). Unknown types/sections are dropped. */
117	export function mapFormFields(dtos: FormFieldDto[]): FormSections {
118	  const result: FormSections = { policyholder: [], vehicle: [] };
119	  for (const dto of dtos) {
120	    if (!isSection(dto.section)) {
121	      console.warn(`Form field "${dto.key}" dropped: unknown section "${dto.section}".`);
122	      continue;
123	    }
124	    if (!isFieldType(dto.type)) {
125	      console.warn(`Form field "${dto.key}" dropped: unknown type "${dto.type}".`);
126	      continue;
127	    }
128	    result[dto.section].push(mapField(dto, dto.section, dto.type));
129	  }
130	  // Array.prototype.sort is stable: equal orders keep CMS order.
131	  result.policyholder.sort((a, b) => a.order - b.order);
132	  result.vehicle.sort((a, b) => a.order - b.order);
133	  return result;
134	}
