362	/** Chilean RUT check-digit validation (modulo 11). */
363	export function isValidRut(raw: string): boolean {
364	  const clean = raw.replace(/[.\s-]/g, '').toUpperCase();
365	  const match = /^(\d{7,8})([0-9K])$/.exec(clean);
366	  if (!match) return false;
367	  const body = match[1];
368	  let sum = 0;
369	  let weight = 2;
370	  for (let i = body.length - 1; i >= 0; i--) {
371	    sum += Number(body[i]) * weight;
372	    weight = weight === 7 ? 2 : weight + 1;
373	  }
374	  const rest = 11 - (sum % 11);
375	  const expected = rest === 11 ? '0' : rest === 10 ? 'K' : String(rest);
376	  return match[2] === expected;
377	}
378	
379	/** raw is yyyy-mm-dd; age computed from local date components. */
380	export function isOfLegalAge(raw: string, legalAge: number, today: Date): boolean {
381	  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);
382	  if (!match) return false;
383	  const y = Number(match[1]);
384	  const m = Number(match[2]);
385	  const d = Number(match[3]);
386	  const birth = new Date(y, m - 1, d);
387	  if (birth.getFullYear() !== y || birth.getMonth() !== m - 1 || birth.getDate() !== d) {
388	    return false;
389	  }
390	  const t = new Date(today.getFullYear(), today.getMonth(), today.getDate());
391	  if (birth.getTime() > t.getTime()) return false;
392	  let age = t.getFullYear() - y;
393	  if (t.getMonth() + 1 < m || (t.getMonth() + 1 === m && t.getDate() < d)) age--;
394	  return age >= legalAge;
395	}
396	
397	function parseYear(raw: string): number | null {
398	  const s = raw.trim();
399	  return /^\d{1,4}$/.test(s) ? Number(s) : null;
400	}
401	
402	export const NAMED_RULES: Record<string, NamedRuleFactory> = {
403	  rut: () => (raw) => isValidRut(raw),
404	  legalAge: (_value, ctx) => (raw) => isOfLegalAge(raw, ctx.legalAge, ctx.today),
405	  maxYearsAgo: (value, ctx) => (raw) => {
406	    const year = parseYear(raw);
407	    return year !== null && value !== null && year >= ctx.today.getFullYear() - value;
408	  },
409	  maxYearsAhead: (value, ctx) => (raw) => {
410	    const year = parseYear(raw);
411	    return year !== null && value !== null && year <= ctx.today.getFullYear() + value;
412	  },
413	};
